import re
# Test the current regex vs what we want
current_regex = re.compile(r'^(?:[a-z0-9\.\-\+]*)://(?:\S+(?::\S*)?@)?(?:[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}|\[[0-9a-f:\.]+\]|[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.(?!-)[a-z0-9-]{1,63}(?<!-))*\.(?!-)[a-z0-9-]{2,63}(?<!-)\.?)?(?::\d{2,5})?(?:[/?#][^\s]*)?\Z', re.IGNORECASE)

# Test with our problematic URL
test_url = 'http://foo/bar@example.com'
print('Current regex matches:', bool(current_regex.match(test_url)))

# Better approach: check if username/password contains unencoded special chars
def validate_user_pass_part(user_pass_part):
    if not user_pass_part:
        return True
    # Remove colon to separate user from password
    if ':' in user_pass_part:
        user, password = user_pass_part.split(':', 1)
    else:
        user = user_pass_part
        password = ''

    # Check for unencoded special characters
    for char in user:
        if char in ':@/':
            return False
    if password:
        for char in password:
            if char in ':@/':
                return False
    return True

# Test our validation logic
url_parts = test_url.split('://', 1)
if len(url_parts) == 2:
    authority = url_parts[1].split('@', 1)
    if len(authority) == 2:
        user_pass = authority[0]
        print('User-pass part:', user_pass)
        print('Validates:', validate_user_pass_part(user_pass))
"

