import sys
print('Python version:', sys.version)

# Try to reproduce the exact scenario
class MockPatch:
    def __init__(self, target, new):
        self.target = target
        self.new = new
        self.attribute_name = None

# Create a simple array-like object that returns array when compared
class ArrayLike:
    def __init__(self, data):
        self.data = data

    def __eq__(self, other):
        # This is what numpy arrays do internally
        if hasattr(other, '__iter__') and not isinstance(other, str):
            try:
                len(other)
                return [True, False]  # Returns array of booleans
            except:
                pass
        return False

    def __repr__(self):
        return f'ArrayLike({self.data})'

# Test the problematic case
patch_obj = MockPatch('target', ArrayLike([1, 2]))
sentinels = [None]

print('Testing: patch_obj.new in sentinels')
try:
    result = patch_obj.new in sentinels
    print('Result:', result)
except Exception as e:
    print('Exception:', e)
    print('Exception type:', type(e).__name__)
"

